def transform(g):
    H=len(g)
    out=[[0]*7 for _ in range(H)]
    for r in range(H):
        for c in range(len(g[0])):
            if g[r][c]==5: r5,c5=r,c
    out[r5][c5-8]=5
    shapes=[]
    for cb in (0,4):
        for rb in range(0,H,4):
            if rb+3>H: break
            col=g[rb][cb]
            if col in MOVES: shapes.append(col)
    r,c=r5+1,c5-8
    for col in shapes:
        dr,dc,L=MOVES[col]
        for i in range(L):
            out[r][c]=col
            if i==L-1: r,c=r+1,c  # next starts below end cell
            else: r,c=r+dr,c+dc
    return out

